"import { Logger } from '@nestjs/common';\nimport speech from '@google-cloud/speech';\n\nexport interface TranscriptionResult {\n  text: string;\n  confidence: number;\n  language: string;\n}\n\nexport class GoogleSpeechService {\n  private readonly logger = new Logger(GoogleSpeechService.name);\n  private client: speech.SpeechClient;\n\n  constructor() {\n    try {\n      // Inicializa o cliente do Google Speech\n      // Requer variável de ambiente GOOGLE_APPLICATION_CREDENTIALS\n      this.client = new speech.SpeechClient();\n    } catch (error) {\n      this.logger.error('Erro ao inicializar Google Speech Client:', error);\n    }\n  }\n\n  async transcribeAudio(audioBuffer: Buffer, mimeType: string = 'audio/wav'): Promise<TranscriptionResult> {\n    try {\n      if (!this.client) {\n        throw new Error('Google Speech Client não inicializado');\n      }\n\n      // Configuração para transcrição\n      const config = {\n        encoding: this.getEncodingFromMimeType(mimeType),\n        sampleRateHertz: 16000,\n        languageCode: 'pt-BR',\n        alternativeLanguageCodes: ['en-US', 'es-ES'],\n        enableAutomaticPunctuation: true,\n        enableWordTimeOffsets: true,\n        model: 'latest_long',\n        useEnhanced: true\n      };\n\n      const audio = {\n        content: audioBuffer.toString('base64')\n      };\n\n      const request = {\n        config,\n        audio\n      };\n\n      // Realiza a transcrição\n      const [response] = await this.client.recognize(request);\n      const transcription = response.results\n        ?.map(result => result.alternatives?.[0]?.transcript || '')\n        .join('\\n') || '';\n\n      const confidence = response.results?.[0]?.alternatives?.[0]?.confidence || 0;\n\n      this.logger.log(`Áudio transcrito com confiança de ${confidence}`);\n      \n      return {\n        text: transcription,\n        confidence,\n        language: 'pt-BR'\n      };\n    } catch (error) {\n      this.logger.error('Erro ao transcrever áudio:', error);\n      throw new Error('Falha ao transcrever áudio com Google Speech');\n    }\n  }\n\n  private getEncodingFromMimeType(mimeType: string) {\n    const encodingMap = {\n      'audio/wav': 'LINEAR16',\n      'audio/mp3': 'MP3',\n      'audio/mpeg': 'MP3',\n      'audio/flac': 'FLAC',\n      'audio/ogg': 'OGG_OPUS',\n      'audio/webm': 'WEBM_OPUS'\n    };\n\n    return encodingMap[mimeType] || 'LINEAR16';\n  }\n}";
